#include <bits/stdc++.h>
using namespace std;

long long gett(long long y, long long m, long long d) {
    if (m < 3) {
        --y;
        m += 12;
    }
    return 365LL * y + y / 4 - y / 100 + y / 400
           + (153LL * m - 457) / 5 + d - 306;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c, d, e, f;
    char sep;

    cin >> a >> sep >> b >> sep >> c;
    cin >> d >> sep >> e >> sep >> f;

    cout << gett(d, e, f) - gett(a, b, c);
    return 0;
}

